  App.renderRegistrationQR=()=>this.renderRegistrationQR();App.renderRegistrations=()=>this.renderRegistrations();App.publicRegister=e=>this.publicRegister(e);App.approveRegistration=id=>this.approveRegistration(id);App.renderUsers=()=>this.renderUsers();App.addUser=e=>this.addUser(e);
