  App.buildSchedulePlan=()=>this.buildSchedulePlan();
  const baseRole=App.applyRole?.bind(App);if(baseRole)App.applyRole=(...args)=>{const r=baseRole(...args);setTimeout(()=>this.applyPermissionsDom(),0);return r};
