 async saveRegistrationConfig(){if(!canEdit('teams','registration'))return U.toast('Không có quyền sửa đăng ký','err');const old=this.registrationConfig(),next={...old,title:$('tk9-reg-title').value.trim()||old.title,deadline:$('tk9-reg-deadline').value,enabled:$('tk9-reg-enabled').checked,token:old.token||this.randomToken(),updatedAt:Date.now()};await T.Data.queueSet('config/registration',next,{type:'REG_CONFIG'});U.toast('Đã lưu cấu hình đăng ký','ok');},
 async rotateRegistrationLink(){if(!canEdit('teams','registration'))return U.toast('Không có quyền','err');if(!confirm('Tạo link mới sẽ làm link/QR cũ hết hiệu lực. Tiếp tục?'))return;const c=this.registrationConfig();await T.Data.queueSet('config/registration',{...c,token:this.randomToken(),updatedAt:Date.now()},{type:'REG_ROTATE'});},
 async copyRegistrationLink(){try{await navigator.clipboard.writeText(this.registrationUrl());U.toast('Đã sao chép link','ok')}catch{const i=$('registration-link');i.select();document.execCommand('copy');U.toast('Đã sao chép link','ok')}},
 async shareRegistrationLink(){const data={title:this.registrationConfig().title,text:`Link đăng ký ${S.name||'Topkey'}`,url:this.registrationUrl()};if(navigator.share)try{return await navigator.share(data)}catch{}return this.copyRegistrationLink();},
