 togglePublicMode(){if(!PAIRING_ENABLED)return;const form=$('registration-public-form'),single=form?.querySelector('input[name="registrationType"]:checked')?.value==='SINGLE';$('tk9-public-team-wrap')?.classList.toggle('hidden',single);$('tk9-public-p2-wrap')?.classList.toggle('hidden',single);$('tk9-public-gender-wrap')?.classList.toggle('hidden',!single);const name=form?.querySelector('[name="name"]'),p2=form?.querySelector('[name="p2"]');if(name)name.required=!single;if(p2)p2.required=!single;const cat=form?.querySelector('[name="category"]')?.value,gender=form?.querySelector('[name="gender"]');if(single&&gender){if(cat==='MEN'){gender.value='MALE';gender.disabled=true}else if(cat==='WOMEN'){gender.value='FEMALE';gender.disabled=true}else gender.disabled=false;}},
 async loadPublicConfigSoon(){for(let i=0;i<30;i++){if(T.Data?.ready)break;await new Promise(r=>setTimeout(r,100))}if(!T.Data?.ready)return;try{const c=await T.Data.read('config');if(c)App.state.config={...App.state.config,...c};this.renderRegistrationQR();this.validatePublicRegistration()}catch{}},
 validatePublicRegistration(){if(location.hash!=='#register')return;const c=this.registrationConfig(),token=new URLSearchParams(location.search).get('reg')||'',expired=c.deadline&&Date.now()>new Date(c.deadline).getTime(),valid=c.enabled&&!!c.token&&token===c.token&&!expired;const form=$('registration-public-form');if(!form)return;let st=$('tk9-public-reg-status');if(!st){st=document.createElement('div');st.id='tk9-public-reg-status';st.className='tk9-security-note';form.prepend(st)}st.textContent=valid?c.title:(expired?'Đã hết hạn đăng ký.':'Link đăng ký không hợp lệ, đã bị thay thế hoặc đang tạm khóa.');form.querySelectorAll('input,select,button,textarea').forEach(x=>x.disabled=!valid);if(valid)this.togglePublicMode();},
 async publicRegister(e){e.preventDefault();const c=this.registrationConfig(),token=new URLSearchParams(location.search).get('reg')||'';if(!c.enabled||token!==c.token)return U.toast('Link đăng ký không còn hiệu lực','err');if(c.deadline&&Date.now()>new Date(c.deadline).getTime())return U.toast('Đã hết hạn đăng ký','err');const f=new FormData(e.target),type=PAIRING_ENABLED?(f.get('registrationType')||'PAIR'):'PAIR',p1=String(f.get('p1')||'').trim(),p2=type==='PAIR'?String(f.get('p2')||'').trim():'',category=String(f.get('category')||S.categories?.[0]||'OPEN'),gender=type==='SINGLE'?(category==='MEN'?'MALE':category==='WOMEN'?'FEMALE':String(f.get('gender')||'')):'';if(!p1||type==='PAIR'&&!p2)return U.toast('Thiếu người tham gia','err');const id=U.id('reg'),name=type==='PAIR'?(String(f.get('name')||'').trim()||`${p1} + ${p2}`):p1,r={id,name,p1,p2,dept:String(f.get('dept')||'').trim(),contact:String(f.get('contact')||'').trim(),category,registrationType:type,gender,seedGroup:type==='SINGLE'?'UNASSIGNED':'',createdAt:Date.now(),status:'PENDING',source:'PUBLIC_QR'};await T.Data.queueSet('registrations/'+id,r,{type:'PUBLIC_REGISTRATION'});e.target.reset();if(PAIRING_ENABLED){const radio=e.target.querySelector('input[value="PAIR"]');if(radio)radio.checked=true;this.togglePublicMode()}U.toast('Đã gửi đăng ký. BTC sẽ duyệt một lần.','ok');},
 renderRegistrations(){const pending=$('registration-list'),approved=$('tk9-approved-singles');if(!pending)return;pending.innerHTML='';if(approved)approved.innerHTML='';const rows=Object.values(App.state.registrations||{}).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));let pc=0,ac=0,paired=0;rows.forEach(r=>{if(r.teamId)paired++;if(r.status==='PENDING'){pc++;pending.appendChild(this.registrationCard(r,true))}else if(r.status==='APPROVED'){ac++;if(r.registrationType==='SINGLE'&&!r.teamId&&approved)approved.appendChild(this.registrationCard(r,false))}});if(!pending.children.length)pending.innerHTML='<p class="muted">Không có đăng ký chờ duyệt.</p>';if(approved&&!approved.children.length)approved.innerHTML='<p class="muted">Chưa có đăng ký đơn đã duyệt chờ ghép.</p>';$('tk9-approved-singles-wrap')?.classList.toggle('hidden',!PAIRING_ENABLED);if($('tk9-reg-pending'))$('tk9-reg-pending').textContent=pc;if($('tk9-reg-approved'))$('tk9-reg-approved').textContent=ac;if($('tk9-reg-paired'))$('tk9-reg-paired').textContent=paired;this.renderRegistrationQR();},
 registrationCard(r,isPending){const d=document.createElement('div');d.className='tk9-reg-entry';const type=r.registrationType==='SINGLE'?'ĐĂNG KÝ 1 NGƯỜI':'ĐĂNG KÝ ĐỘI';d.innerHTML=`<div class="row"><div><b>${esc(type)} · ${esc(r.category||'')}</b><div>${esc(r.name||'')} · ${esc(r.p1||'')}${r.p2?' + '+esc(r.p2):''}</div><div class="meta">${esc(r.dept||'')} ${r.gender?'· '+esc(r.gender):''}</div></div><div class="tk9-actions"></div></div>`;const a=d.querySelector('.tk9-actions');if(isPending){const ok=document.createElement('button');ok.className='btn mini ok';ok.textContent=r.registrationType==='SINGLE'?'Duyệt VĐV':'Duyệt → Check-in';ok.onclick=()=>this.approveRegistration(r.id);a.appendChild(ok);const reject=document.createElement('button');reject.className='btn mini danger';reject.textContent='Từ chối';reject.onclick=()=>this.rejectRegistration(r.id);a.appendChild(reject)}else if(r.registrationType==='SINGLE'){const label=document.createElement('label');label.className='tk9-seed';label.innerHTML=`Nhóm <select><option value="UNASSIGNED">Chưa phân</option><option>A</option><option>B</option><option>C</option></select>`;label.querySelector('select').value=r.seedGroup||'UNASSIGNED';label.querySelector('select').onchange=e=>this.setSeed(r.id,e.target.value);a.appendChild(label)}return d;},
 async approveRegistration(id){if(!canEdit('teams','registration'))return U.toast('Không có quyền duyệt','err');const r=App.state.registrations?.[id];if(!r||r.status!=='PENDING'||r.teamId)return U.toast('Đăng ký này đã được xử lý','info');if(r.registrationType==='SINGLE'){const after={...r,status:'APPROVED',reviewedAt:Date.now(),reviewedBy:T.Auth.user?.uid||''};await T.Data.queueSet('registrations/'+id,after,{type:'REG_APPROVE_SINGLE'});await T.Data.audit('APPROVE','registration',id,r,after);return}const teamId=U.id('team'),team={id:teamId,code:App.nextCode?App.nextCode('T',App.state.teams):'T'+String(Object.keys(App.state.teams||{}).length+1).padStart(3,'0'),name:r.name||`${r.p1} + ${r.p2}`,p1:r.p1,p2:r.p2,dept:r.dept,category:r.category,checkedIn:false,withdrawn:false,createdAt:Date.now(),registrationId:id,registrationSource:'PUBLIC_QR'},after={...r,status:'APPROVED',teamId,reviewedAt:Date.now(),reviewedBy:T.Auth.user?.uid||''},up={};up[T.Data.path('teams/'+teamId)]=team;up[T.Data.path('registrations/'+id)]=after;await T.Data.queueMulti(up,{type:'REG_APPROVE'});await T.Data.audit('APPROVE','registration',id,r,team);U.toast('Đã duyệt. Đội đã chuyển sang danh sách Check-in.','ok');},
