 async setSeed(id,seed){const r=App.state.registrations?.[id];if(!r||r.registrationType!=='SINGLE')return;await T.Data.queueSet('registrations/'+id,{...r,seedGroup:seed,updatedAt:Date.now()},{type:'REG_SEED'});this.drawDraft=null;},
 eligibleSingles(category){return Object.values(App.state.registrations||{}).filter(r=>r.registrationType==='SINGLE'&&r.category===category&&r.status==='APPROVED'&&!r.teamId);},
 shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a;},
 drawValid(a,b,cat){if(cat==='MIX')return a.gender!==b.gender&&['MALE','FEMALE'].includes(a.gender)&&['MALE','FEMALE'].includes(b.gender);if(cat==='MEN')return a.gender==='MALE'&&b.gender==='MALE';if(cat==='WOMEN')return a.gender==='FEMALE'&&b.gender==='FEMALE';return true;},
